package com.franco.desco.application.catalog.service;
import com.franco.desco.application.catalog.CatalogCommands.*;import com.franco.desco.application.catalog.port.in.CatalogUseCase;import com.franco.desco.application.catalog.port.out.CatalogPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.catalog.CatalogModels;import java.util.List;
public final class CatalogApplicationService implements CatalogUseCase{private final CatalogPersistencePort p;public CatalogApplicationService(CatalogPersistencePort p){this.p=p;}public AppResult<PageResult<CatalogModels.Item>> list(ListCatalog c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"CATALOGO_LISTADO","CATALOGO_NO_LISTADO",AppStatus.BAD_REQUEST);}public AppResult<Long> create(CreateCatalog c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"CATALOGO_CREADO","CATALOGO_NO_CREADO");}public AppResult<Void> update(UpdateCatalog c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"CATALOGO_ACTUALIZADO","CATALOGO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}public AppResult<Void> disable(DisableCatalog c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.disable(c,i,m),"CATALOGO_DESHABILITADO","CATALOGO_NO_DESHABILITADO",AppStatus.BAD_REQUEST);}public AppResult<List<CatalogModels.Department>> departments(ListDepartments c){return ApplicationResults.ok(p.departments(),"DEPARTAMENTOS_LISTADOS","GEOGRAFIA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<List<CatalogModels.Province>> provinces(ListProvinces c){return ApplicationResults.ok(p.provinces(c),"PROVINCIAS_LISTADAS","GEOGRAFIA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<List<CatalogModels.District>> districts(ListDistricts c){return ApplicationResults.ok(p.districts(c),"DISTRITOS_LISTADOS","GEOGRAFIA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<List<CatalogModels.PopulationCenter>> populationCenters(ListPopulationCenters c){return ApplicationResults.ok(p.populationCenters(c),"CENTROS_POBLADOS_LISTADOS","GEOGRAFIA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}}
